package com.yp.luminote.app.rendering.gpu

/** DEBUG-only AGSL sources contain the unmistakable GPU submission witness. */
internal object GpuMeshShaders {
    const val FULL = "uniform vec4 resolvedColor; uniform float animatedAlpha; uniform int uDebugGpuWitness; float2 main(const Varyings v, out float4 color) { if (uDebugGpuWitness != 0) { color = v.coverage > .5 ? float4(1.0,0.0,1.0,1.0) : float4(0.0,1.0,1.0,1.0); return v.position; } float a = clamp(v.coverage * animatedAlpha, 0.0, 1.0); color = float4(resolvedColor.rgb * a, a); return v.position; }"
    const val LIGHT = "uniform vec4 resolvedColor; uniform float baseAlpha; uniform float source; uniform float forwardLength; uniform float reverseLength; uniform float sourceRadius; uniform float tailEnergy; uniform float coreEnergy; uniform float bloomEnergy; uniform int fadeOnly; uniform int uDebugGpuWitness; float wrapped(float x) { return fract(x + 1.0); } float smoothUnion(float a,float b) { float x=clamp(a,0.0,1.0); float y=clamp(b,0.0,1.0); float x2=x*x; float y2=y*y; return (x2*x+y2*y)/(x2+y2+.000001); } float profile(float distance, float length) { if (length <= .0001) return 0.0; float t=clamp(distance/length,0.0,1.0); float sourceRelease=smoothstep(sourceRadius,sourceRadius+.012,distance); float tail=(1.0-smoothstep(.10,.96,t))*tailEnergy; float core=smoothstep(.52,.84,t)*(1.0-smoothstep(.84,1.0,t))*coreEnergy; return sourceRelease*smoothUnion(tail,core); } float2 main(const Varyings v, out float4 color) { if (uDebugGpuWitness != 0) { color = fract(v.contour * 24.0) > .5 ? float4(1.0,0.0,1.0,1.0) : float4(0.0,1.0,1.0,1.0); return v.position; } float forward=wrapped(v.contour-source); float reverse=wrapped(source-v.contour); float field=smoothUnion(profile(forward,forwardLength),profile(reverse,reverseLength)); float sourceDistance=min(forward,reverse); float bloom=(1.0-smoothstep(0.0,sourceRadius+.0001,sourceDistance))*bloomEnergy; if (fadeOnly != 0) field=0.0; float transverse=smoothstep(0.0,1.0,v.lateral); float a=clamp(transverse*smoothUnion(field,bloom)*baseAlpha,0.0,1.0); color=float4(resolvedColor.rgb*a,a); return v.position; }"
}
